// The typing root: every Hono instance, middleware and context is parameterized by AppEnv.
import type { Context } from 'hono';
import type { JwtVariables } from 'hono/jwt';

/**
 * `Env` is generated by `wrangler types` from wrangler.jsonc (bindings and `secrets.required`), so a new
 * binding is typed here the moment it is declared there - never restate it by hand.
 */
export type AppEnv = { Bindings: Env; Variables: JwtVariables };
export type AppContext = Context<AppEnv>;
